/* XP and unlocks (docs/LESSONS_SPEC.md §3). earn() is the only caller of gainXP: it records every unlock in s.kept (all classes), queues the hero's new ones for their card, and saves once. `before` is ready() taken before the answer was applied. */
function ready() {
  return ABILITIES[s.hero].filter(a => unlocked(s, a)).map(a => a.id);
}

function keep() {
  Object.values(ABILITIES).flat().forEach(a => {
    if (a.gate > 0 && unlocked(s, a) && !s.kept.includes(a.id)) {
      s.kept.push(a.id);
    }
  });
}

/* v2:edu the slot each new ability was auto-equipped into (playtest S2-8), for its banner */
const autoSlots = {};
function earn(n, before = ready()) {
  const lv = s.level;
  if (n > 0) {
    gainXP(s, n);
  }
  keep();
  const found = ABILITIES[s.hero].filter(a => unlocked(s, a) && !before.includes(a.id) && !unlockQueue.includes(a));
  unlockQueue.push(...found);
  /* v2:edu */for (const a of found) { autoSlots[a.id] = autoEquip(s, s.hero, a.id, ABILITIES[s.hero][0].id); emitAbilityUnlocked(a, {hero: s.hero, subject: a.subject, gate: a.gate, level: s.level, mastery: abilityMastery(s, a.subject), slot: autoSlots[a.id]}); }
  /* v2:edu */if (found.length) barKey = '';
  persist();
  /* oct26-midgame: a level won in town (Library XP) left the hero's max health at the old level until the next adventure */
  if (lv !== s.level && !world.level) world.refreshStats?.();
  return lv !== s.level ? s.level : 0;
}

/* Abilities unlocked by XP won inside a level (the hero level half of a gate): named on the result card and
   celebrated with the unlock card once the player leaves it (learning-flow fix, 17 Oct). */
let levelUnlocks = [];
function showLevelUnlocks(next = forceClose) { if (!levelUnlocks.length) { next(); return; } unlockQueue.push(...levelUnlocks.splice(0)); unlockCard(next); }
function combatXP(n) {
  const lv = earn(n);
  const got = unlockQueue.splice(0);
  /* v2:levels -- inside a level a level-up is announced on the results card, never as a toast that lands later in town */
  const inLevel = !!world.level; if (inLevel && lv && world.run) world.run.levelUp = lv;
  if (inLevel) levelUnlocks.push(...got);
  const message = [lv && !inLevel ? `Level ${lv} reached!` : '', ...(inLevel ? [] : got).map(a => `${a.name} unlocked! Equip it at Home.`)].filter(Boolean).join(' ');
  if (message) toast(message);
  if (lv && !inLevel) levelUpBanner(lv); /* v2:ui */
}

const toGo = a => Math.max(0, Math.ceil(levelXP(xpLevel(a)) - totalXP(s)));

/* (playtest 14 Oct) "Master 3 History topics", not "3 topics to master of History" */
function knowledgeGoal(a, sub) {
  const n = lessonsToUnlock(s, a);
  /* oct24-polish2 (playtest r3 D3): the count of the road so far, so a long road still shows each topic landing */
  const done = TOPICS.filter(t => t.subject === a.subject && mastered(s, t)).length;
  return n.lessons ? `Master ${n.lessons} more ${sub} topic${n.lessons === 1 ? '' : 's'} (${done} of ${done + n.lessons} done)` : n.reachable ? `${sub} topics ✓` : `Train ${sub} at the Library`;
}
function gateLine(a) {
  if(asleep(s,a))return 'Finish your first Library lesson to awaken this ability';
  const k = abilityMastery(s, a.subject) + 1e-8 >= a.gate;
  const l = s.level >= xpLevel(a);
  const sub = SUBJECTS[a.subject].name;
  if (k && !l) {
    return `Knowledge ✓ · reach hero level ${xpLevel(a)}: win a level (${toGo(a)} XP to go)`;
  } else if (!k && l) {
    return `Hero level ✓ · ${knowledgeGoal(a, sub)}`;
  } else if (!k && !l) {
    return `${knowledgeGoal(a, sub)} · reach hero level ${xpLevel(a)}`;
  } else {
    return `Ready to unlock`;
  }
}

function gateBars(a,labels=false) {
  if(asleep(s,a))return '<p class="subtle">Complete any lesson at the Library to equip your first ability.</p>';
  const kp = Math.min(100, a.gate>0?abilityMastery(s, a.subject) / a.gate * 100:100);
  const lp = Math.min(100, totalXP(s) / Math.max(1, levelXP(xpLevel(a))) * 100);
  return `${labels?'<span class="gate-bar-label">Knowledge</span>':''}<div class="progress" aria-label="Knowledge"><i style="width:${kp}%"></i></div>${labels?'<span class="gate-bar-label">Hero level</span>':''}<div class="progress xp" aria-label="Hero level"><i style="width:${lp}%"></i></div>`;
}

function gateSmall(a) {
  const sub = SUBJECTS[a.subject].name;
  const mastery = abilityMastery(s, a.subject).toFixed(1);
  const level = xpLevel(a);
  /* v2:edu goals in lessons, never percentages */const n = lessonsToUnlock(s, a);
  return `${n.lessons ? `${n.lessons} topic${n.lessons === 1 ? '' : 's'} to master` : n.reachable ? 'Topics ✓' : 'Library training'} · Hero level ${level}` + (s.level >= level ? ' ✓' : '');
}

function nextUnlock(subject) {
  return ABILITIES[s.hero].filter(a => !unlocked(s, a) && (!subject || a.subject === subject))
    .sort((a, b) => {
      const needA = a.gate - abilityMastery(s, a.subject);
      const needB = b.gate - abilityMastery(s, b.subject);
      if (needA > 1e-8 && needB > 1e-8) {
        return needA - needB;
      } else if (needA <= 1e-8 && needB <= 1e-8) {
        return xpLevel(a) - xpLevel(b);
      } else {
        return needA > 1e-8 ? -1 : 1;
      }
    })[0];
}

function targetText(subject) {
  const a = nextUnlock(subject);
  return a ? /* v2:edu */goalLine(s, a) : ABILITIES[s.hero].some(x=>x.subject===subject)?'All available abilities for this subject are unlocked.':'Explore another subject to work toward your next ability.';
}
