function picStart(spec,dur=2.5,el=$('#lesson-pic')){if(!el){pic=null;return;}/* v2:edu */const paint=painter(spec);el.setAttribute('aria-label',paint.label);/* v2:theater */const rm=reducedMotion(),th=[].concat(spec).some(x=>x&&x.t==='theater');dur=picLength(spec,dur);pic={el,ctx:crispCtx(el),spec,paint,th,t:rm?dur:0,dur,rm,live:picLive(spec)};picPaint();}
