 show('lesson',header(`${esc(SUBJECTS[t.subject].name)} · ${stageName(t)}`,`${esc(t.title)} · Step ${i+1} of ${n}`)+`<div class="lesson" data-topic="${t.id}" data-step="${i}"><div class="lesson-body" role="region" aria-label="Lesson content" tabindex="0"><p class="lesson-say" aria-live="polite">${esc(st.say).replace(/(^|\s)(-[A-Za-z]+)/g,'$1<span style="white-space:nowrap">$2</span>')}</p><div class="lesson-visual">${st.eq?`<p class="lesson-eq${hb?.eq?' held':''}">${esc(st.eq)}</p>`:''}<canvas id="lesson-pic" width="640" height="280" role="img" aria-label="${esc(describe(shown))}"></canvas></div>${c?`<div class="lesson-check" data-check="${i}"><h3>Try it</h3>${retired?`<p>${esc(String(c.prompt).replace(/^Try it:\s*/i,'').replace(/^[a-z]/,m=>m.toUpperCase()))}</p><p class="lesson-worked">Worked example: the answer is <strong>${esc(String(c.answer))}</strong>. ${esc(c.hint)}</p>`:`<p>${esc(String(c.prompt).replace(/^Try it:\s*/i,'').replace(/^[a-z]/,m=>m.toUpperCase()))}</p><div class="lesson-answers">${opts.map((o,k)=>`<button data-answer="${esc(String(o))}"><span class="tag" aria-hidden="true">${k+1}</span><span class="choice-text">${esc(String(o))}</span></button>`).join('')}</div><p id="lesson-feedback" aria-live="polite"></p><p id="lesson-hint" class="subtle"></p>`}</div>`:''}</div><div class="lesson-footer"><div class="lesson-dots" aria-hidden="true">${t.steps.map((_,k)=>`<i class="${k===i?'on':k<i?'done':''}"></i>`).join('')}</div><div class="actions"><button id="lesson-restart" class="ghost" ${i?'':'disabled'}>Start over</button><button id="lesson-back" ${i?'':'disabled'}>Back</button><button id="lesson-replay">Replay</button><button id="lesson-next" class="primary">${i===n-1?finishLabel(s,t):'Next'}</button></div></div></div>`);
