/* v2:edu Practice (playtest S2-3): a sitting of PRACTICE_SIZE questions from the topic pool, unpractised ones first. */
const PRACTICE_SIZE=10,practiceSize=(s,t)=>practiceSitting(s,t,PRACTICE_SIZE);
function practiceButton(t){if(mastered(s,t))return '';const g=testReady(s,t);return g.practice>=g.needed?'':`<button data-practice="${t.id}" title="${esc(PRACTICE_WHY)}">Practice (${g.practice}/${g.needed})</button>`;}
function lessonCard(t,open=true){
  const r=s.lessons[t.id]||{},co=t.grade>=9?courseOf(t.id):null,tag=co?`${esc(co.course.name)} · Unit ${co.index+1}`:`${esc(SUBJECTS[t.subject].name)} · ${esc(lessonGradeLabel(t))}`;
  if(!open)return `<div class="lesson-card shut" style="--accent:${SUBJECTS[t.subject].color}"><span class="tag">${tag}</span><strong>${esc(t.title)}</strong><span class="subtle">${esc(t.goal)}</span><span class="lesson-track">${co?'Opens when Grade 8 is mastered, or after a High School placement.':`Opens when Grade ${t.grade-1} is mastered.`}</span></div>`;
  return `<div class="lesson-card" style="--accent:${SUBJECTS[t.subject].color}"><span class="tag">${tag}</span><strong>${esc(t.title)}</strong><span class="subtle">${esc(t.goal)}</span>${/* v2:edu four steps that light up (playtest m15) */topicProgressHTML(s,t,{compact:true})}${left(s,t)<30?`<span class="lesson-track">${left(s,t)} questions left</span>`:''}<div class="lesson-actions"><button data-lesson="${t.id}">${r.at>0?'Resume lesson':'Start lesson'}</button>${/* 25 Oct: a mastered topic has no Quiz button (it can only retire questions now; the lesson stays open for review) */mastered(s,t)?'':`<button data-quiz="${t.id}">Quiz</button>`}${/* v2:edu */practiceButton(t)}${(()=>{if(r.pts>0)return `<span class="tag">Mastered ✓</span>`;const g=testReady(s,t);return g.ready?`<button data-test="${t.id}">Mastery test</button>`:`<button data-test="${t.id}" disabled title="${esc(`Finish the lesson, pass the quiz, and practise ${g.needed} questions first.`)}">Mastery test locked</button><span class="subtle">${/* v2:edu */`Test opens after: ${g.lesson?'':'lesson, '}${g.quiz?'':`quiz ${g.quizNeed}/${g.quizSize} right, `}practice ${g.practice}/${g.needed}`}</span>`;})()}</div></div>`;
}

function wireLessons(){
  $$('[data-lesson]').forEach(el=>el.onclick=()=>startLesson(el.dataset.lesson));
  $$('[data-quiz]').forEach(el=>el.onclick=()=>startSitting(el.dataset.quiz,'quiz'));
  /* the Library's Next card, when the next goal is an adventure: straight to the world map, at that pad (polish, 19 Oct) */$$('[data-go-adventure]').forEach(el=>el.onclick=()=>openWorldMap({at:el.dataset.goAdventure}));
  /* v2:edu practice draws from the whole topic pool (playtest S2-3) */$$('[data-practice]').forEach(el=>el.onclick=()=>startSitting(el.dataset.practice,'practice'));
  $$('[data-test]').forEach(el=>el.onclick=()=>startSitting(el.dataset.test,'test'));
  $$('[data-placement]').forEach(el=>el.onclick=()=>startPlacement(el.dataset.placement));
  /* v2:edu */$$('[data-placement-middle]').forEach(el=>el.onclick=()=>startPlacement(el.dataset.placementMiddle,'middle'));
  /* v2:edu High School placement (docs/HIGH_SCHOOL_SPEC.md §3) */$$('[data-placement-high]').forEach(el=>el.onclick=()=>startPlacement(el.dataset.placementHigh,'high'));
}

function panelKey(key){
  const open=$$('[data-answer]:not(:disabled)');
  if(['1','2','3','4','5','6','7','8'].includes(key) && open.length){
    $$('[data-answer]')[+key-1]?.click();
    return true;
  }
  /* M opened the Oakhaven map, so M closes it too (playtest 14 Oct: the second press did nothing). */
  if(key==='m' && modalView==='village-map'){ close(); return true; }
  /* fast travel (25 Oct): T on the town map opens the picker; T in the picker closes it */
  if(key===s.settings.bindings.travel && modalView==='village-map'){ fastTravel(); return true; }
  if((key===s.settings.bindings.travel||key==='m') && modalView==='travel'){ close(); return true; }
  if(modalView!=='lesson') return false;
  if(key==='arrowright') {
    $('#lesson-next')?.click();
    return true;
  }
  else if(key==='arrowleft' && $('#lesson-back:not(:disabled)')) {
    $('#lesson-back').click();
    return true;
  }
  else if(key==='r') {
    $('#lesson-replay')?.click();
    return true;
  }
  return false;
}

const BACK={appearance:()=>home(),course:()=>library(),review:()=>reviewSummary(),'review-summary':()=>library(),placement:()=>leavePlacement(),'placement-summary':()=>library(),training:()=>trainingSummary(),'checkpoint-loadout':()=>pause(true),abandon:()=>pause(true),'import-confirm':()=>settings(),lesson:()=>library(),'lesson-quiz':()=>leaveSitting()};/* oct24-progress (playtest r3): a lesson result has no Back target, so one Escape closes it (it took two: result, then the Library) */
let sitting = null;

const readyAbilitiesForRoad=()=>ready();
function startSitting(id, kind) {
    if(needLessons([id],()=>startSitting(id,kind)))return;
    const t = lessonTopic(id);
    if (!t) return;
    const test = kind === 'test' ? beginMasteryTest(s, t) : null;
    const items = test ? test.items : pickItems(s, t, kind === 'practice' ? /* v2:edu */practiceSize(s, t) : QUIZ_SIZE);
    if (!items.length) {
        sitting = null;
        /* v2:edu an exhausted pool masters the topic (the exhaustion rule), even when placement retired its last questions */
        /* (the local `ready` below shadows ready() here, so the unlocked list is read directly) */
        const before = ABILITIES[s.hero].filter(a => unlocked(s, a)).map(a => a.id), ex = masterExhausted(s, t);
        if (ex.mastered) { earn(ex.xp, before); persist(); }
        show('lesson-summary', header(kind === 'test' ? 'Mastery test' : kind === 'practice' ? 'Practice' : 'Quiz', esc(t.title)) + `<div class="result" data-kind="${kind}"><p>Every question in this topic is retired — you answered each one correctly twice.${ex.mastered ? ` That masters the topic: +${+topicPoints(t).toFixed(2)} ${stageName(t)} ${esc(SUBJECTS[t.subject].name)} · +${ex.xp} XP.` : ''}</p>${abilityProgressHTML(s,t.subject,{celebrate:ex.mastered})}<div class="modal-actions"><button id="lesson-library" class="primary">Back to the Library</button></div></div>`);
        $('#lesson-library').onclick = ()=>library({subject:t.subject});wireRoadPreview(readyAbilitiesForRoad().some(id=>!before.includes(id)));
        return;
    }
    // The test only opens once the lesson, the quiz and the practice are done. Readiness is
    // settled here, when the sitting begins, so its own answers cannot unlock it part way through.
    const ready = kind === 'test' ? testReady(s, t) : {ready: true};
    if (!ready.ready) {
        sitting = null;
        show('lesson-summary', header('Mastery test', esc(t.title)) + `<div class="result" data-kind="test"><p>The mastery test opens when the lesson, quiz and practice are done.</p><p class="subtle">${ready.lesson ? 'Lesson ✓' : 'Watch the lesson'} · ${ready.quiz ? 'Quiz ✓' : `Pass the quiz (${ready.quizNeed} of ${ready.quizSize} right)`} · Practice ${ready.practice}/${ready.needed}</p><div class="modal-actions">${ready.lesson ? '' : `<button data-lesson="${t.id}">Start lesson</button>`}${ready.quiz ? '' : `<button data-quiz="${t.id}">Quiz</button>`}${/* v2:edu */ready.practice < ready.needed ? `<button data-practice="${t.id}">Practice (${ready.practice}/${ready.needed})</button>` : ''}<button id="lesson-library" class="primary">Back to the Library</button></div></div>`);
        wireLessons();
        $('#lesson-library').onclick = ()=>library({subject:t.subject});
        return;
    }
    sitting = { id, kind, items, i: 0, right: {}, xp: 0, mastered: false, beforeAbilities: readyAbilitiesForRoad(), ready: test ? test.ready : ready.ready, requiredSkills: test?.requiredSkills };
    sittingQuestion();
}

function sittingQuestion() {
    const t = lessonTopic(sitting.id), q = sitting.items[sitting.i], n = sitting.items.length;
    let done = false;
    show('lesson-quiz', header(`${esc(SUBJECTS[t.subject].name)} · ${stageName(t)}`, esc(t.title)) +
        `<div class="question" data-q="${q.id}" data-kind="${sitting.kind}"><div class="question-reading" role="region" aria-label="Question and diagram" tabindex="0"><span class="tag">${sitting.kind === 'test' ? 'MASTERY TEST' : sitting.kind === 'practice' ? /* v2:edu */'PRACTICE' : 'QUIZ'} · ${sitting.i + 1} of ${n}</span>${sittingPipsHTML(n, sitting.i, sitting.items.map(x => sitting.right[x.id]))}` +
        (questionPictureHTML(askedPic(q))) +
        `<h3${q.prompt.length <= 40 ? ' class="big"' : ''}>${esc(q.prompt)}</h3>${readButtonHTML(q.prompt)}</div>${choiceFormHTML(q) || `<form id="quiz-form"><input id="quiz-answer" aria-label="Your answer" placeholder="Type your answer…" autocomplete="off" ${/* v2:edu decimals need a point key on phones */q.numeric ? 'inputmode="decimal"' : ''} required><div class="modal-actions"><button type="submit" id="quiz-check" class="primary">Check</button></div></form>`}<div id="quiz-feedback" aria-live="polite"></div><div class="modal-actions"><button id="quiz-end">Stop</button><button id="quiz-next" class="primary" hidden>${sitting.i + 1 < n ? 'Next question' : 'See results'}</button></div></div>`);
    const askedSpec = askPic(askedPic(q));
    if ($('#quiz-pic')) drawPic(crispCtx($('#quiz-pic')), askedSpec, 1);
    quizZoom(askedSpec);
    $('#quiz-form').onsubmit = e => {
        e.preventDefault();
        if (done || !$('#quiz-answer').value.trim()) return;
        done = true;
        submitSitting(q, $('#quiz-answer').value);
    };
    $('#quiz-next').onclick = () => unlockCard(() => {
        sitting.i++;
        sitting.i < n ? sittingQuestion() : sittingSummary();
    }, {tryIt: false});
    $('#quiz-end').onclick = leaveSitting;
    $('[data-close]').onclick = leaveSitting;
    wireChoices($('#quiz-form'), q);
    focusAnswers($('#quiz-form')) || $('#quiz-answer').focus({preventScroll:true});
}

/* 25 Oct (learning-loop playtest): once an explanation shows, the question box shrinks to a strip (style.css); it scrolls to the
   question's words so the child still sees what was asked, with the picture a scroll away. */
/* oct25-quizpolish: only when the words are not already in full view (a picture beside the prompt keeps the progress row in sight) */
function questionInView(){const rd=$('.question-reading'),h=rd?.querySelector('h3');if(!rd||!h||!$('#quiz-feedback .feedback>p'))return;const a=h.getBoundingClientRect(),b=rd.getBoundingClientRect();if(a.top<b.top||a.bottom>b.bottom)rd.scrollTop+=a.top-b.top-6;}
function submitSitting(q, input) {
    /* 25 Oct (learning-loop playtest): the 25th practice answer used to pass silently, so a child kept going through the rest of the sitting not knowing the test had opened */
    const tTopic = sitting.kind === 'practice' ? lessonTopic(sitting.id) : null, wasReady = tTopic ? testReady(s, tTopic).ready : true;
    const before = ready(), r = grade(s, q, input), lv = earn(r.xp, before);
    sitting.right[q.id] = r.ok;
    sitting.xp += r.xp;
    if (r.mastered) sitting.mastered = true;
    $('#quiz-answer').disabled = true;
    $('#quiz-check').disabled = true;
    $('#quiz-feedback').innerHTML = `<div class="feedback">` + answerMomentHTML({ok: r.ok, xp: r.xp, nth: Object.values(sitting.right).filter(Boolean).length - 1, answer: q.answer, level: lv, mastered: r.mastered}) + spellNote(input, q) + (r.ok ? '' : `<p>${esc(q.explanation)}</p>${readButtonHTML(`The answer is ${q.answer}. ${q.explanation||''}`)}` + (shownPic(q) && !$('#quiz-pic') ? `<canvas id="lesson-pic" width="640" height="280" role="img" aria-label="${esc(describe(shownPic(q)))}"></canvas>` : '')) + `</div>`;
    /* 25 Oct (first-hour playtest): "Try it again" sits right under the explanation, above the worked picture, so it shows without scrolling */
    if(!r.ok){mountAnswerReview($('#quiz-feedback'),q,{stage:s.schoolMode});const rv=$('#quiz-feedback .answer-review'),pc=$('#quiz-feedback #lesson-pic');if(rv&&pc)pc.before(rv);rv?.addEventListener('toggle',()=>{if(rv.open)rv.scrollIntoView?.({block:'nearest'});});}
    { const pips = $('.question .am-pips'); if (pips) pips.outerHTML = sittingPipsHTML(sitting.items.length, sitting.i, sitting.items.map(x => sitting.right[x.id])); }
    if (!wasReady && testReady(s, tTopic).ready) { $('#quiz-feedback .feedback')?.insertAdjacentHTML('beforeend', `<p class="test-open-note"><b>Practice ${PRACTICE_NEEDED}/${PRACTICE_NEEDED}: the mastery test is open!</b> ${sitting.i + 1 < sitting.items.length ? 'Stop here to take it, or keep practising.' : 'See results to take it.'}</p>`); if (sitting.i + 1 < sitting.items.length) $('#quiz-end').textContent = 'Stop here'; }
    /* oct25-quizpolish: when the question already shows its picture, the worked picture plays there instead of a second copy in the card */
    if (!r.ok && shownPic(q)) picStart({ ...shownPic(q), solve: true }, 2.5, $('#lesson-pic') || $('#quiz-pic'));
    questionInView();
    sfx(r.ok ? 'correct' : 'wrong');
    $('#quiz-next').hidden = false;
    $('#quiz-next').focus();
}
function sittingSummary(){
  const t=lessonTopic(sitting.id),k=sitting.kind,answered=Object.keys(sitting.right).length,score=Object.values(sitting.right).filter(Boolean).length;let body='',lv=0;
  /* one square per question answered, so the squares agree with the score beside them (polish, 19 Oct) */const done=sitting.items.filter(x=>x.id in sitting.right),pips=answered?sittingPipsHTML(done.length,-1,done.map(x=>sitting.right[x.id]),`${score} of ${answered} right`):'';
  if(k==='practice'){
    /* v2:edu practice records nothing but the answers themselves, which is what the practice count reads */persist();const g=testReady(s,t);
    body = `<h2 class="am-score">${score} / ${answered}</h2>${pips}<p>${answered?`Practice ${g.practice}/${g.needed}.${g.ready?' The mastery test is open!':g.practice>=g.needed?' Practice complete. Finish the lesson and quiz to open the mastery test.':''}`:'You stopped before answering. Nothing is lost.'}</p><p class="subtle">${esc(PRACTICE_WHY)}</p>`;
  } else if(k==='quiz'){
    const r=recordQuiz(s,t,score);persist();
    /* a quiz left part-way says so as its headline, not "First try done." (polish, 19 Oct) */const passed=testReady(s,t).quiz,early=answered&&answered<sitting.items.length,stopped=`You stopped after ${answered} of ${sitting.items.length} questions.`;
    body = `<h2 class="am-score">${score} / ${answered}</h2>${pips}<p>${!answered?'You stopped before answering. Nothing is lost.':early&&!passed?`${stopped} Nothing is lost.`:(r.improved&&!r.first?(passed&&(r.before||0)<Math.ceil(PASS*QUIZ_SIZE-1e-9)?'Quiz passed! A new best score.'/* 25 Oct: a retake that first passes says so */:'A new best score!'):r.first?(passed?'Quiz passed!':'First try done.')/* playtest 14 Oct pass 2: a first 2/5 read "A new best score!" */:`Your best: ${r.best} / ${QUIZ_SIZE}`)}</p>${(()=>{const g=testReady(s,t);return (early&&passed?`<p class="subtle">${stopped}</p>`:'')+(answered&&!g.quiz?`<p>${g.quizNeed} of ${g.quizSize} right passes the quiz. Try again whenever you like.</p>`:'');})()}`;
  } else {
    const before=ready(),r=finishTest(s,t,{items:sitting.items,right:sitting.right,ready:sitting.ready,requiredSkills:sitting.requiredSkills});lv=earn(r.xp,before);sitting.xp+=r.xp;
    body = `${r.first?'<span class="am-seal" aria-hidden="true"></span>':''}<h2 class="am-score">${r.score} / ${r.total}</h2>${/* the test is scored out of every question, so it shows every square */answered?sittingPipsHTML(sitting.items.length,-1,sitting.items.map(x=>sitting.right[x.id]),`${r.score} of ${r.total} right`):''}`;
    if(r.first){
      sitting.mastered=true;
      body += `<div class="unlock mastered"><span class="tag">TOPIC MASTERED</span><h3>“${esc(t.title)}” mastered!</h3><p>+${+topicPoints(t).toFixed(2)} ${stageName(t)} ${esc(SUBJECTS[t.subject].name)}</p></div>`;/* late playtest 24 Oct: this card said +40 XP above a +80 XP chip; the chip below is the one total */
    } else if(r.passed){
      body += `<p>Passed again. This topic is already mastered.</p>`;
    } else {
      body += `<p>${r.score>=Math.ceil(PASS*r.total-1e-9)-2?'Almost there':'Not yet'}: ${Math.ceil(PASS*r.total-1e-9)} of ${r.total} right passes the test. Retakes are free, with no waiting, and every right answer still counted.</p>`;
      if(r.missed.length){
        body += `<div class="modal-actions">`;
        for(const k2 of r.missed){
          body += `<button data-replay-step="${t.steps.findIndex(x=>x.skill===k2)}">Rewatch: ${esc(t.skills[k2])}</button>`;
        }
        body += `</div>`;
      }
    }
  }
  const x=sitting.xp,celebrate=sitting.mastered,newAbility=ready().some(id=>!sitting.beforeAbilities.includes(id));sitting=null;
  unlockCard(()=>{
    show('lesson-summary',header(k==='test'?'Mastery test':k==='practice'?'Practice':'Quiz',esc(t.title))+`<div class="result" data-kind="${k}">${body}${rewardChips(x,lv)}${/* v2:edu */topicProgressHTML(s,t)}${abilityProgressHTML(s,t.subject,{celebrate})}${(()=>{const g=testReady(s,t);return mastered(s,t)||g.ready?'':`<p class="subtle test-gate">Mastery test opens after: ${g.lesson?'lesson ✓':'the lesson'} · ${g.quiz?'quiz ✓':`quiz ${g.quizNeed} of ${g.quizSize} right`} · practice ${g.practice}/${g.needed}</p>`;})()}<div class="modal-actions">${mastered(s,t)?'':`<button id="start-quiz">${k==='quiz'?'Retake quiz':'Quiz'}</button>`}${/* v2:edu */practiceButton(t)}${(()=>{const g=testReady(s,t);return !mastered(s,t)&&g.ready?'<button id="start-test">Mastery test</button>':'';})()}<button id="lesson-library" class="primary">Back to the Library</button></div></div>`);
    $$('[data-replay-step]').forEach(b=>b.onclick=()=>startLesson(t.id,+b.dataset.replayStep));
    {const sq=$('#start-quiz');if(sq)sq.onclick=()=>startSitting(t.id,'quiz');}{const st=$('#start-test');if(st)st.onclick=()=>startSitting(t.id,'test');}$('#lesson-library').onclick=()=>library({subject:t.subject});wireLessons();primaryNext(t);wireRoadPreview(newAbility);
  });
}

/* A preview only draws the existing hero animation. It never casts or changes a save. */
function wireRoadPreview(newAbility=false){
 const button=$('[data-road-preview]'),cv=$('.road-canvas');if(!button||!cv)return;
 if(newAbility){button.remove();cv.remove();return;}
 let playing=false;
 button.onclick=()=>{if(playing)return;playing=true;cv.hidden=false;/* oct24-r3 playtest: at 1280x720 the preview opened below the fold, so the 1.6 s clip played unseen */cv.scrollIntoView?.({block:'nearest'});const start=performance.now(),still=settingsReducedMotion(s),state='ab-'+button.dataset.roadPreview;
  const paint=now=>{if(!cv.isConnected){playing=false;return;}const t=(now-start)/1000;drawHeroFigure(cv,s.hero,{state,time:still?.25:t,front:false,plain:true});if(t<1.6&&!still)requestAnimationFrame(paint);else playing=false;};requestAnimationFrame(paint);};
}

/* A course's exam review (docs/design/COURSES.md): twelve mixed questions from the course's mastered units, no timer.
   Answers count like practice (two right answers retire a question; a wrong one changes nothing) and earn XP; the end
   shows a score for each unit and points to the weakest one. */
let review=null;
const REVIEW_SIZE=12,EXAM_SIZE=20;
/* mode 'review': up to 12 questions dealt evenly across the mastered units; mode 'exam': a practice exam of up to 20, shared
   out by each unit's weight on the real exam (EXAMS, the midpoint of its range; 1 where the course has no exam data) */
function startReview(courseId,mode='review'){
 if(needLessons((courseById(courseId)?.units||[]).map(u=>u.topic),()=>startReview(courseId,mode)))return;
  const c=courseById(courseId);if(!c)return;
  const ids=new Set(TOPICS.map(t=>t.id)),ex=EXAMS[c.id],name=mode==='exam'?'Practice exam':'Exam review';
  const units=c.units.map((u,i)=>({u,i,t:ids.has(u.topic)?lessonTopic(u.topic):null})).filter(x=>x.t&&mastered(s,x.t));
  const items=!units.length?[]:mode==='exam'?pickPracticeExam(s,examPracticeGroups(c.id,units.map(x=>x.t),POOL,ITEMS),EXAM_SIZE):pickReview(s,units.map(x=>x.t),REVIEW_SIZE);
  if(!items.length){show('review',header(name,esc(c.name))+`<p>${units.length?(mode==='exam'&&ex?.framework?'No current-exam questions remain in your mastered units. Use Exam review for enrichment, or master another unit.':'Every question in your mastered units is retired. Well done.'):'Master a unit of this course first.'}</p><div class="modal-actions"><button id="review-library" class="primary">Back to the Library</button></div>`);$('#review-library').onclick=library;return;}
  review={course:c,mode,items,i:0,right:{},xp:0};reviewQuestion();
}
/* A course page (docs/design/COURSE_QUALITY.md, "a tool to study for the AP exam"): the exam's format and each unit's weight
   from the public course description, the student's progress in every unit, the outline topics they have practised
   least, and the practice exam. Nothing here is timed; the page says how long the real sections are. */
function coursePage(courseId){
 if(needLessons((courseById(courseId)?.units||[]).map(u=>u.topic),()=>coursePage(courseId)))return;
  const c=courseById(courseId);if(!c)return;const ex=EXAMS[c.id];
  const units=c.units.map((u,i)=>{const t=TOPIC_IDS.has(u.topic)?lessonTopic(u.topic):null,pool=t?POOL[t.id]:[],right=pool.filter(id=>(s.answers[id]||0)>=1).length;return {u,i,t,pool,right,w:ex?.weights?.[i]};});
  const mastered_=units.filter(x=>x.t&&mastered(s,x.t)).length;
  const status=x=>!x.t?'<span class="subtle">Coming</span>':mastered(s,x.t)?'<strong class="course-done">Mastered ✓</strong>':x.right?`${x.right} of ${x.pool.length} answered right<span class="am-minibar" aria-hidden="true"><i style="width:${Math.round(x.right/x.pool.length*100)}%"></i></span>`:topicOpen(s,x.t)?'Not started':'<span class="subtle">Locked</span>';
  /* the outline topics with the smallest share of their questions answered right, in units the student has started */
  const weak=units.filter(x=>x.t&&x.right).flatMap(x=>(x.t.outline||Object.entries(x.t.skills).map(([k,name])=>[null,name,[k]])).map(([code,name,ks])=>{const ids=x.pool.filter(id=>ks.includes(ITEMS[id].skill)),r=ids.filter(id=>(s.answers[id]||0)>=1).length;return {x,code,name,r,n:ids.length,share:ids.length?r/ids.length:1};}))
   .filter(w=>w.n&&w.share<1).sort((a,b)=>a.share-b.share).slice(0,3);
  const pace=ex?ex.mcq[1]/ex.mcq[0]:0;
  show('course',header(esc(c.name),c.exam?'Course page · every unit, your progress, and the exam':'Course page · every unit and your progress')+`<div class="course-page">`+
   `<h3>${ex?.framework?'Learning units':'Units'}</h3><table class="course-table"><thead><tr><th>Unit</th>${ex?`<th>${ex.framework?'Current exam coverage':'On the exam'}</th>`:''}<th>Your progress</th><th></th></tr></thead><tbody>${units.map(x=>`<tr><td>${x.i+1}. ${esc(x.u.name)}</td>${ex?`<td>${x.w?`${x.w[0]}-${x.w[1]}%`:esc(ex.learningNotes?.[x.i]||'')}</td>`:''}<td>${status(x)}</td><td>${x.t&&topicOpen(s,x.t)?`<button data-lesson="${x.t.id}">Lesson</button>`:''}</td></tr>`).join('')}</tbody></table>`+
   `<h3>Review next</h3>${weak.length?`<ul class="course-weak">${weak.map(w=>`<li>Unit ${w.x.i+1}, ${w.code?`${esc(w.code)} `:''}${esc(w.name)}: ${w.r} of ${w.n} answered right <button data-practice="${w.x.t.id}">Practice</button></li>`).join('')}</ul>`:'<p class="subtle">Start a unit and the topics you have practised least will show here.</p>'}`+
   (ex?`<h3>The exam${ex.edition?` · ${esc(ex.edition)}`:''}</h3>${ex.note?`<p>${esc(ex.note)}</p>`:''}${ex.framework?`<h4>Current exam units</h4><table class="course-table"><thead><tr><th>Exam unit</th><th>Multiple-choice weighting</th></tr></thead><tbody>${ex.framework.map((g,i)=>`<tr><td>${i+1}. ${esc(g.name)}</td><td>${g.weight[0]}-${g.weight[1]}%</td></tr>`).join('')}</tbody></table>`:''}<table class="course-table"><thead><tr><th>Section</th><th>What</th><th>Time</th><th>Score</th></tr></thead><tbody>${ex.sections.map(([n,w,m,p])=>`<tr><td>${esc(n)}</td><td>${esc(w)}</td><td>${m} min</td><td>${p}%</td></tr>`).join('')}</tbody></table><p class="subtle">On the real exam the multiple-choice section gives about ${Math.round(pace*10)/10} minute${pace===1?'':'s'} a question. PixelQuest never times you; time yourself if you want to. From the public course description: check the current one before your exam.${ex.source?` <a href="${esc(ex.source)}" target="_blank" rel="noopener">College Board exam details</a>`:''}</p>`:'')+
   `<p class="course-review">${mastered_?`<button data-exam="${c.id}" class="primary">Practice exam</button> <span class="subtle">${EXAM_SIZE} questions from your ${mastered_} mastered unit${mastered_>1?'s':''}${ex?', shared across available exam content using the published weight ranges':''}, scored by unit.</span> <button data-review="${c.id}">Exam review</button>`:'<span class="subtle">The practice exam opens when you master a unit.</span>'}</p>`+
   `${c.exam?`<p class="subtle ap-note">${esc(AP_NOTE)}</p>`:''}<div class="modal-actions"><button id="course-library">Back to the Library</button></div></div>`);
  wireLessons();$$('[data-exam]').forEach(el=>el.onclick=()=>startReview(el.dataset.exam,'exam'));$$('[data-review]').forEach(el=>el.onclick=()=>startReview(el.dataset.review));$('#course-library').onclick=library;
}
function reviewQuestion(){
  const r=review,q=r.items[r.i],n=r.items.length,co=courseOf(q.topic);let done=false;
  const label=r.mode==='exam'?'Practice exam':'Exam review';
  show('review',header(`${label} · ${esc(r.course.name)}`,esc(co?`Unit ${co.index+1}: ${co.unit.name}`:lessonTopic(q.topic).title))+`<div class="question" data-q="${q.id}" data-kind="review"><span class="tag">${label.toUpperCase()} · ${r.i+1} of ${n}</span>`+
   (questionPictureHTML(askedPic(q)))+
   `<h3>${esc(q.prompt)}</h3>${readButtonHTML(q.prompt)}${choiceFormHTML(q)||`<form id="quiz-form"><input id="quiz-answer" aria-label="Your answer" placeholder="Type your answer…" autocomplete="off" ${q.numeric?'inputmode="decimal"':''} required><div class="modal-actions"><button type="submit" id="quiz-check" class="primary">Check</button></div></form>`}<div id="quiz-feedback" aria-live="polite"></div><div class="modal-actions"><button id="quiz-end">Stop</button><button id="quiz-next" class="primary" hidden>${r.i+1<n?'Next question':'See results'}</button></div></div>`);
  if($('#quiz-pic'))drawPic(crispCtx($('#quiz-pic')),askPic(askedPic(q)),1);
  $('#quiz-form').onsubmit=e=>{e.preventDefault();if(done||!$('#quiz-answer').value.trim())return;done=true;
   const before=ready(),g=grade(s,q,$('#quiz-answer').value),lv=earn(g.xp,before);r.right[q.id]=g.ok;r.xp+=g.xp;persist();
   $('#quiz-answer').disabled=true;$('#quiz-check').disabled=true;
   $('#quiz-feedback').innerHTML=`<div class="feedback">${answerMomentHTML({ok:g.ok,xp:g.xp,nth:r.i,answer:q.answer,level:lv})}${spellNote($('#quiz-answer').value,q)}${g.ok?'':`<p>${esc(q.explanation)}</p>${readButtonHTML(`The answer is ${q.answer}. ${q.explanation||''}`)}`}</div>`;
   sfx(g.ok?'correct':'wrong');$('#quiz-next').hidden=false;$('#quiz-next').focus();};
  $('#quiz-next').onclick=()=>{r.i++;r.i<n?reviewQuestion():reviewSummary();};
  $('#quiz-end').onclick=reviewSummary;$('[data-close]').onclick=reviewSummary;wireChoices($('#quiz-form'),q);focusAnswers($('#quiz-form'))||$('#quiz-answer').focus({preventScroll:true});
}
function reviewSummary(){
  const r=review;if(!r){library();return;}review=null;
  const asked=r.items.filter(q=>q.id in r.right),score=asked.filter(q=>r.right[q.id]).length,by=new Map();
  for(const q of asked){const k=q.topic,v=by.get(k)||{right:0,n:0};v.n++;if(r.right[q.id])v.right++;by.set(k,v);}
  const rows=[...by].map(([id,v])=>{const co=courseOf(id);return {id,v,label:co?`Unit ${co.index+1}: ${co.unit.name}`:lessonTopic(id).title};});
  const weak=rows.filter(x=>x.v.right<x.v.n).sort((a,b)=>a.v.right/a.v.n-b.v.right/b.v.n)[0];
  show('review-summary',header(r.mode==='exam'?'Practice exam':'Exam review',esc(r.course.name))+`<div class="result" data-kind="review"><h2>${score} / ${asked.length}</h2>${asked.length?`<div class="notes">${rows.map(x=>`<span>${esc(x.label)}: <strong>${x.v.right} / ${x.v.n}</strong></span>`).join('')}</div>${weak?`<p>Worth another look: ${esc(weak.label)}.</p>`:'<p>Every one right. You are ready for this part of the course.</p>'}`:'<p>You stopped before answering. Nothing is lost.</p>'}<p class="subtle">+${r.xp} XP</p><div class="modal-actions">${weak?`<button data-lesson="${weak.id}">Rewatch ${esc(weak.label.split(':')[0])}</button>`:''}<button id="review-again">${r.mode==='exam'?'Another practice exam':'Another review'}</button><button id="review-course">Course page</button><button id="review-library" class="primary">Back to the Library</button></div></div>`);
  wireLessons();$('#review-again').onclick=()=>startReview(r.course.id,r.mode);$('#review-course').onclick=()=>coursePage(r.course.id);$('#review-library').onclick=library;
}
function leaveSitting(){
  if(!sitting){library();return;}
  /* Oct 19: stopping before the first answer is not a result; go straight back instead of a "0 / 0, +0 XP" summary */
  if((sitting.kind==='quiz'||sitting.kind==='practice')&&!Object.keys(sitting.right).length){const subject=lessonTopic(sitting.id).subject;sitting=null;library({subject});return;}
  if(sitting.kind==='quiz'||sitting.kind==='practice'){sittingSummary();return;}
  const subject=lessonTopic(sitting.id).subject;sitting=null;library({subject});
  $('#modal-content .notes')?.insertAdjacentHTML('beforeend','<span class="sitting-note">Test left unfinished. Your right answers still count for XP.</span>');
}
function nextQuestion(){if(session.count>=10){trainingSummary();return;}question=selectQuestion(s,session);if(!question){trainingSummary(true);return;}answered=false;const a=nextUnlock(session.subject),m=a?abilityMastery(s,session.subject):mastery(s,session.subject);show('training',header(SUBJECTS[session.subject].name,`${LEVELS[session.level]} · ${question.topic} · Question ${session.count+1} of 10`)+`<div class="question"><div class="training-reading" role="region" aria-label="Training question" tabindex="0"><span class="tag">${a?`WORKING TOWARD ${esc(a.name)}`:'GROWING YOUR KNOWLEDGE'}</span><div class="progress" style="--accent:${SUBJECTS[session.subject].color}" role="progressbar" aria-label="Progress toward ${a?esc(a.name):'further mastery'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(a?Math.min(100,m/a.gate*100):m)}"><i style="width:${a?Math.min(100,m/a.gate*100):m}%"></i></div><span class="subtle">${a?(a.gate-m<=1e-8?esc(gateLine(a)):`${m.toFixed(1)} / ${a.gate} toward abilities · ${a.gate-m<1?'Almost there':`${(a.gate-m).toFixed(1)} to go`}`):`${m.toFixed(1)}% mastery`}</span><h3>${esc(question.prompt)}</h3></div><form id="answer-form" aria-label="Answer choices">${question.options?`<div class="answers">${[...question.options].sort(()=>Math.random()-.5).map((a,i)=>`<button type="button" data-answer="${esc(a)}"><span class="tag">${i+1}</span> &nbsp; ${esc(a)}</button>`).join('')}</div>`:`<input id="answer" aria-label="Your answer" placeholder="Type your answer…" autocomplete="off" ${question.numeric?'inputmode="decimal"':''} required><div class="modal-actions"><button type="submit" class="primary">Check answer</button></div>`}</form><div id="feedback" aria-live="polite"></div><div class="modal-actions"><button id="end-training" class="ghost">Finish session</button></div></div>`);$('[data-close]').onclick=()=>trainingSummary();$('#end-training').onclick=()=>trainingSummary();$$('[data-answer]').forEach(el=>el.onclick=()=>submitAnswer(el.dataset.answer));$('#answer-form').onsubmit=e=>{e.preventDefault();submitAnswer($('#answer').value);};if($('#answer'))$('#answer').focus({preventScroll:true});else focusAnswers($('#answer-form'));}
function submitAnswer(input){if(answered)return;answered=true;const before=ready(),r=answer(s,session,question,input),lv=earn(r.ok?XP.correct:0,before);$$('#answer-form button,#answer-form input').forEach(el=>el.disabled=true);$('#feedback').innerHTML=`<div class="feedback"><strong>${r.ok?`That’s right. +${r.gain.toFixed(1)}% level mastery · +${XP.correct} XP${lv?` · Hero level ${lv}!`:''}`:`The answer is ${esc(question.answer)}.`}</strong><p>${esc(question.explanation)}</p>${!r.ok?'<p>Your mastery is unchanged. You can keep practicing.</p>':''}</div><div class="modal-actions"><button id="next-question" class="primary">${unlockQueue.length?'Discover your new ability':session.count>=10?'See your progress':'Next question'}</button></div>`;if(!r.ok)mountAnswerReview($('#feedback'),question,{stage:s.schoolMode});$('#end-training').parentElement.append($('#next-question'));$('#next-question').focus({preventScroll:true});$('#next-question').onclick=()=>{if(unlockQueue.length)unlockCard(nextQuestion,{tryIt:false});else nextQuestion();};if(r.ok)sfx('correct');else sfx('wrong');}
function abilityDetails(a){/* oct25-tryit P10: the card used the raw base shield (54) while combat gave 64 at hero level 4. It now says what the ability does with the numbers combat gives today (abilityNumbers: shield and heal grow with max health). A raw damage number is no longer quoted: a hit scales with the hero and the foe's armour (ui/ability-panel.js). Short facts stay on one line each (first-hour playtest 24 Oct). */const n=abilityNumbers(s,a),facts=[a.cost>0?`${a.cost} ${CLASSES[s.hero].resource.toLowerCase()}`:null,`Wait ${a.cd} seconds between uses`].filter(Boolean).map(t=>t.replace(/ /g,'\u00a0')).join(' · ');return `${abilityWhat(a,CLASSES[s.hero].signature,n).replace(/\.$/,'')} · ${facts}`;}
/* oct25-tryit P9: "Try it in a fight". The card offers it on the last card of a chain, outside a level, and not in the middle of a
   quiz, test, practice, training or placement run (those call sites pass {tryIt:false}); the ability is then remembered (tryPending)
   and the next result screen offers it instead. tryItFight equips it, starts the fight game/try-it.js picks the normal way (replay
   rules apply) and names its key when the fight starts. */
var tryPending=null,tryHint=null,tryGlow=-1;/* var and function declarations: show() calls offerTryIt and may run before this line during start-up */
function tryOffer(){if(!tryPending||world.level)return null;const a=ABILITIES[s.hero]?.find(x=>x.id===tryPending);if(!a||!unlocked(s,a)||asleep(s,a)){tryPending=null;return null;}const l=tryItLevel(s);return l?{a,l}:null;}
function tryWhere(l){return l.replay?`A short fight in ${l.name}, a level you have won.`:`Your next adventure: ${l.name}.`;}
function tryItFight(id){const a=ABILITIES[s.hero]?.find(x=>x.id===id),l=tryItLevel(s);if(!a||!unlocked(s,a)||asleep(s,a)||!l)return;
 const ids=s.loadouts[s.hero]??=activeLoadout(s),{slot,replaced}=tryItSlot(activeLoadout(s),id),old=replaced&&ABILITIES[s.hero].find(x=>x.id===replaced);ids[slot]=id;persist();
 tryPending=null;unlockQueue.length=0;sfx('ui');
 if(startLevel(l.id,{tier:'normal'})){const touch=document.documentElement.classList.contains('m-mode');tryHint=tryItHint(a.name,{key:touch?String(slot+1):keyLabel(abilityKeys(s)[slot]),touch,replaced:old?.name||''});tryGlow=slot;}}
/* oct25-tryit P1: "Find your level in <Subject>" (study-unlock.js placementNudge) opens that subject's shelf with the existing
   Find-your-starting-point check open on it; the child still chooses to start it. */
function findLevel(subject){if(!SUBJECTS[subject])return;sfx('ui');library({subject});const start=$('#modal-content .hs-start');if(!start)return;start.open=true;const pick=start.querySelector('#placement-subject');if(pick){pick.value=subject;pick.dispatchEvent(new Event('change'));}start.querySelector('summary')?.focus({preventScroll:true});requestAnimationFrame(()=>start.isConnected&&start.scrollIntoView?.({block:'start'}));}
/* a result screen after an unlock that came mid-sitting offers the same button once, beside its own buttons */
function offerTryIt(){const o=tryOffer();if(!o||!['lesson-summary','training-summary','placement-summary'].includes(modalView))return;const row=$('#modal-content').querySelector('.actions,.modal-actions');if(!row||row.querySelector('[data-try-it]'))return;row.insertAdjacentHTML('afterbegin',`<button type="button" class="try-it-offer" data-try-it="${esc(o.a.id)}" title="${esc(tryWhere(o.l))}">Try ${esc(o.a.name)} in a fight</button>`);tryPending=null;}
