function unlockCard(next,{tryIt=true}={}){const a=unlockQueue.shift();if(!a){next();return;}fanfare();if(!world.level)tryPending=a.id;const t=tryIt&&!unlockQueue.length?tryOffer():null;if(t)tryPending=null;show('unlock',/* v2:edu */unlockBannerHTML(a,{heroName:CLASSES[s.hero].name,subjectName:SUBJECTS[a.subject].name,subjectColor:SUBJECTS[a.subject].color,level:xpLevel(a),description:abilityDetails(a),slot:autoSlots[a.id]??-1,icon:abilityIcon(a,s.hero,64),tryIt:t?{label:'Try it in a fight',where:tryWhere(t.l)}:null,...(a.gate===0?{awakening:true,why:`Your training awakens ${a.name}.`,quote:'“Every page you finish wakes something in you. Go on, try it.”\u00a0—\u00a0The\u00a0Archivist'}:{why:`Your ${SUBJECTS[a.subject].name} knowledge made this possible.`})}));$('#unlock-next').onclick=()=>unlockQueue.length?unlockCard(next,{tryIt}):next();}
