function community(message=''){const profile=activeProfile()?.id||'p1';show('community',header('Village noticeboard','A place for village news and your ideas.')+communityBoardHTML(readSuggestions(profile)));$('#suggestion-status').textContent=message||$('#suggestion-status').textContent;const input=$('#suggestion-text');input.oninput=()=>{$('#suggestion-count').textContent=`${input.value.length} / ${SUGGESTION_LIMIT} characters`;};$('#suggestion-form').onsubmit=e=>{e.preventDefault();const result=saveSuggestion(profile,$('input[name="suggestion-category"]:checked')?.value,input.value);if(result.ok){community(result.message);$('#suggestion-text').focus({preventScroll:true});}else $('#suggestion-status').textContent=result.message;};}
