function abilityCards(){return ABILITIES[s.hero].map((a,i)=>{const ready=unlocked(s,a)&&/* v2:edu */!asleep(s,a),ids=s.loadouts[s.hero]||[],slot=ids.indexOf(a.id);return `<div class="card ability-card ${ready?'':'locked'}" style="--accent:${SUBJECTS[a.subject].color}"><span class="symbol">${/* v2:ui */abilityIcon(a,s.hero)}</span><span class="tag">${a.branch}</span><h3>${a.name}</h3><span class="gate">${ready?'UNLOCKED':esc(gateLine(a))}</span><p>${esc(abilityLine(a,abilityNumbers(s,a)))} · ${a.cost>0?`${a.cost} ${CLASSES[s.hero].resource.toLowerCase()} · `:''}${a.cd}s between uses</p>${ready?`<select data-equip="${a.id}" aria-label="Equip ${a.name}"><option value="-1">${slot<0?'Not equipped':'Unequip'}</option>${[0,1,2,3].map(n=>`<option value="${n}" ${slot===n?'selected':''}>Slot ${n+1}</option>`).join('')}</select>`:asleep(s,a)?'':`<div class="ability-requirements">${gateBars(a,true)}</div>`}</div>`;}).join('');}
