 const det=$('.inv-detail');let doll={};const peek=id=>{const it=GEAR_ITEM[id];if(det&&it){det.innerHTML=itemDetailHTML(s,s.hero,id);wireDetail();}doll=it?.slot==='weapon'?{art:it.art||null}:it?.slot==='chest'?{set:it.set||null}:{};if(it?.art)previewHeroArt(s.hero,it.art);};
