 {const cv=$('.inv-herocv'),still=document.documentElement.dataset.motion==='reduced';if(cv?.getContext?.('2d')){const tick=()=>{if(!cv.isConnected)return;drawHeroFigure(cv,s.hero,{time:still?0:performance.now()/1000,...doll});requestAnimationFrame(tick);};tick();}}
