/* First-time hint (14 Oct): a hero with abilities on the bar sees "Press 1-4 to use your abilities" above the bar, and
   the slots pulse, for the first 15 s of a level. 24 Oct playtest: it came back at every level start. It now stops for
   good after 3 casts (settings.castUses, then settings.castTip) or after it has been shown at 4 level starts
   (settings.castHints), whichever comes first, and it waits while a toast such as "This visit" is up, so the two never stack. */
let hintRun=null,hintAt=0,hintCd={},hintCounted=null,hintCastIn=null;
function abilityHint(ids,p){const el=$('#ability-hint');if(!el)return;/* up to 15 s each time a level starts, so it never sits over a whole fight */if(hintRun!==world.level){hintRun=world.level;hintAt=performance.now()+1500;hintCd={};}const keys=ids.map((id,i)=>id?esc(keyLabel(abilityKeys(s)[i])):null).filter(Boolean);if(!s.settings.castTip&&keys.length){let cast=0;for(const id of ids)if(id){const c=p.cooldowns[id]||0;if(c>(hintCd[id]||0)+.05)cast++;hintCd[id]=c;}if(cast){hintCastIn=world.level;s.settings.castUses=(s.settings.castUses|0)+cast;if(s.settings.castUses>=3)s.settings.castTip=true;persist();}}const toastUp=$('#toast').classList.contains('show');/* oct25-phone2 review: +300 ms, so the hint never fades in over a toast still fading out (they share the phone's bottom strip) */if(toastUp)hintAt=Math.max(hintAt,performance.now()+300);const on=!!world.level&&!((world.level.encounter?.readable||document.documentElement.classList.contains('m-mode'))&&bannerActive(world))&&!world.controlsTutorial&&!!keys.length&&!s.settings.castTip&&(hintCounted===world.level||(s.settings.castHints|0)<4)&&hintCastIn!==world.level&&!toastUp&&performance.now()>=hintAt&&performance.now()-hintAt<15000&&world.flow!=='victory'&&!mapOn&&!$('#modal').open;if(on&&hintCounted!==world.level){hintCounted=world.level;s.settings.castHints=(s.settings.castHints|0)+1;persist();}el.classList.toggle('show',on);$('#hotbar').classList.toggle('hint-pulse',on);if(!on){if(el.dataset.fit){delete el.dataset.fit;for(const k of ['left','maxWidth','bottom','top','whiteSpace','textAlign'])el.style[k]='';}return;}const m=document.documentElement.classList.contains('m-mode');/* oct25-phone2: on a phone the hint takes the same bottom strip as a fight toast (they never show together), beside the buttons it points at, instead of over the foes */if(m&&!el.dataset.fit){const b=compactToastBox();if(b){el.dataset.fit='1';Object.assign(el.style,{left:b.center+'px',maxWidth:b.width+'px',bottom:b.bottom+'px',top:'auto',whiteSpace:'normal',textAlign:'center'});}}const t=m?(keys.length===1?'Tap your ability button to use it':'Tap the ability buttons to use your abilities'):keys.length===1?`Press <kbd>${keys[0]}</kbd> to use your ability`:`Press ${keys.map(k=>'<kbd>'+k+'</kbd>').join(' / ')} to use your abilities`;if(el.dataset.t!==t){el.dataset.t=t;el.innerHTML=t;}}
function avoidPromptHotbar(){const el=$("#prompt"),hb=$("#hotbar"),stage=$("#stage");if(!el||!hb||!el.textContent.trim()||typeof getComputedStyle==="function"&&getComputedStyle(hb).visibility==="hidden")return;const a=el.getBoundingClientRect(),b=hb.getBoundingClientRect();if(a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top){const sr=stage.getBoundingClientRect(),anchored=el.style.transform.includes("-100%");el.style.top=`${Math.round(b.top-sr.top-(anchored?8:a.height+8))}px`;el.style.bottom="auto";}}
function placePrompt(at,box){const el=$('#prompt');if(!at){if(el.style.cssText)el.style.cssText='';return;}const r=$('#world').getBoundingClientRect(),sr=$('#stage').getBoundingClientRect();if(!r.width)return;/* never over the town quest plank: its bottom plus the bubble's own height is the floor */const ob=$('#objective')?.getBoundingClientRect(),floor=ob&&ob.height?ob.bottom-sr.top+el.offsetHeight+6:0;let L=Math.round(r.left-sr.left+at[0]*r.width);let T=Math.round(Math.max(floor,r.top-sr.top+Math.max(.06,at[1])*r.height));/* never over the hero plate, gold row and menu buttons: slide right of them (the bed's Sleep sat on the gold row) */const hl=$('.hud-left')?.getBoundingClientRect(),w=(el.firstElementChild||el).offsetWidth,h=el.offsetHeight;if(hl&&hl.width&&T-h<hl.bottom-sr.top+12&&T>hl.top-sr.top&&L-w/2<hl.right-sr.left){/* oct24-progress (playtest r3): sliding right put Sleep over the dresser; drop just under the plate instead, still over the bed, unless that is far from the spot */const below=Math.round(hl.bottom-sr.top+h+10);if(below-T<=120)T=below;else L=Math.round(hl.right-sr.left+w/2+8);}/* first-hour playtest 24 Oct: at the south gate the hero stands right where the bubble sat and it hid the head; lift it above the hero (about 50 px tall at 1x) */const hp=world.player,cm=world.camera;if(hp&&cm?.width){const sc=r.width/cm.width,hx=r.left-sr.left+(hp.x-cm.x+cm.width/2)*sc,hy=r.top-sr.top+(hp.y-cm.y+cm.height/2)*sc,top=hy-52*sc;if(Math.abs(L-hx)<w/2+14*sc&&T>top&&T-h<hy)T=Math.round(Math.max(floor,top-4));}/* oct25-exploit2 O3: a drawn footprint (town.js hubPrompt box, the roster board) the floor pushed the prompt onto: beside it instead, on the side with room */if(box){const bx0=r.left-sr.left+box[0]*r.width,by0=r.top-sr.top+box[1]*r.height,bx1=r.left-sr.left+box[2]*r.width;if(T>by0-2){if(bx0-8-w>=8)L=Math.round(bx0-8-w/2);else if(bx1+8+w<=sr.width-8)L=Math.round(bx1+8+w/2);}}el.style.cssText=`left:${L}px;top:${T}px;right:auto;bottom:auto;width:max-content;transform:translate(-50%,-100%)`;const hb=$("#hotbar");if(hb&&getComputedStyle(hb).visibility!=="hidden"){const a=el.getBoundingClientRect(),b=hb.getBoundingClientRect();if(a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top){const x=b.left-sr.left-a.width/2-8;if(x>=a.width/2+8&&x<=sr.width-a.width/2-8)el.style.left=`${Math.round(x)}px`;else el.style.top=`${Math.round(b.top-sr.top-8)}px`;}}}
/* newplayer-oct27: the tutorial's "use something" step points where the objective already sends the child (the south gate, the Library), not back into the house they just left; the nearest usable thing is only the fallback */
function tutorialUsable(){try{const st=nextStep(s,{room:hubState().room});if(tutorialGuidanceNP(st)){const t=hubGuidanceTargetNP(st.target,nextPowerNP(s)?.subject);if(t)return t;}}catch{}return hubNearestUsable();}
